conditional.example:
age = 18

if age >= 18:
    print("Adult")
elif age >= 13:
    print("Teenager")
else:
    print("Child")

score = 85
if score >= 90:
    grade = "A"
elif score >= 80:
    grade = "B"
else:
    grade = "C"
print(f"Grade: {grade}")   # Grade: B

username = "admin"
password = "1234"
if username == "admin" and password == "1234":
    print("Login success!")

loop.example:
fruits = ["apple", "banana", "cherry"]
for fruit in fruits:
    print(fruit)

for i in range(5):           # 0,1,2,3,4
    print(i)

count = 0
while count < 5:
    print(f"Count: {count}")
    count += 1               # ត្រូវកែប្រែ count គ្រប់ដង កុំឲ្យ infinite loop

for num in range(10):
    if num == 5:
        break                # ឈប់ពេលដល់ 5
    if num % 2 != 0:
        continue             # រំលងលេខសេស
    print(num)
